class Solution:
    def judgePoint24(self, cards: List[int]) -> bool:
        EPS = 1e-6

        def solve(nums: List[float]) -> bool:
            if len(nums) == 1:
                return abs(nums[0] - 24) < EPS
            n = len(nums)
            for i in range(n):
                for j in range(i + 1, n):
                    a, b = nums[i], nums[j]
                    rest = [nums[k] for k in range(n) if k != i and k != j]
                    results = [a + b, a - b, b - a, a * b]      # six ways to merge the pair
                    if abs(b) > EPS:
                        results.append(a / b)
                    if abs(a) > EPS:
                        results.append(b / a)
                    for v in results:
                        if solve(rest + [v]):                   # table shrinks by one value
                            return True
            return False

        return solve([float(x) for x in cards])

class Solution:
    def addOperators(self, num: str, target: int) -> List[str]:
        n, out = len(num), []

        def dfs(i: int, expr: str, value: int, last: int) -> None:
            if i == n:
                if value == target:
                    out.append(expr)
                return
            for j in range(i + 1, n + 1):
                s = num[i:j]
                if len(s) > 1 and s[0] == "0":
                    break                                       # no leading zeros: prune
                cur = int(s)
                if i == 0:
                    dfs(j, s, cur, cur)                         # first operand, no operator
                else:
                    dfs(j, expr + "+" + s, value + cur, cur)
                    dfs(j, expr + "-" + s, value - cur, -cur)
                    dfs(j, expr + "*" + s, value - last + last * cur, last * cur)

        dfs(0, "", 0, 0)
        return out

