def brute_force(robot: "Robot") -> None:
    # Same DFS, but backtracking retraces the whole path to the start and replays it to the parent.
    D = ((-1, 0), (0, 1), (1, 0), (0, -1))
    visited, heading = set(), [0]

    def face(d: int) -> None:
        while heading[0] != d:
            robot.turnRight(); heading[0] = (heading[0] + 1) % 4

    def walk(path: List[int], forward: bool) -> None:    # replay the path, or undo it backwards
        for d in (path if forward else reversed(path)):
            face(d if forward else (d + 2) % 4); robot.move()

    def dfs(r: int, c: int, path: List[int]) -> None:
        visited.add((r, c)); robot.clean()
        for d, (dr, dc) in enumerate(D):
            if (r + dr, c + dc) not in visited:
                face(d)
                if robot.move():
                    dfs(r + dr, c + dc, path + [d])
                    walk(path + [d], False); walk(path, True)   # O(depth) commands per backtrack

    dfs(0, 0, [])

def brute_force(grid: List[List[int]]) -> int:
    # Every ordering of the empty cells; keep those forming an adjacent chain start -> ... -> end.
    cells = {v: (r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v in (1, 2)}
    empties = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 0]

    def adjacent(a, b) -> bool:
        return abs(a[0] - b[0]) + abs(a[1] - b[1]) == 1

    count = 0
    for order in permutations(empties):                     # k! orderings, checked only when complete
        chain = (cells[1],) + order + (cells[2],)
        if all(adjacent(chain[i], chain[i + 1]) for i in range(len(chain) - 1)):
            count += 1
    return count

