class Solution:
    def findLadders(self, beginWord: str, endWord: str, wordList: List[str]) -> List[List[str]]:
        words = set(wordList)
        if endWord not in words:
            return []
        L = len(beginWord)
        parents: Dict[str, Set[str]] = {}               # word -> words in the previous layer
        layer, found = {beginWord}, False
        words.discard(beginWord)
        while layer and not found:
            nxt = defaultdict(set)
            for w in layer:
                for i in range(L):
                    for ch in "abcdefghijklmnopqrstuvwxyz":
                        nb = w[:i] + ch + w[i + 1:]
                        if nb in words:
                            nxt[nb].add(w)
            words -= nxt.keys()                         # remove the whole layer, not word by word
            parents.update(nxt)
            layer, found = set(nxt), endWord in nxt

        paths: List[List[str]] = []

        def backtrack(w: str, path: List[str]) -> None:
            if w == beginWord:
                paths.append(path[::-1])
                return
            for p in parents[w]:
                backtrack(p, path + [p])

        if found:
            backtrack(endWord, [endWord])
        return paths

