class Solution:
    def slidingPuzzle(self, board: List[List[int]]) -> int:
        nbr = [[1, 3], [0, 2, 4], [1, 5], [0, 4], [1, 3, 5], [2, 4]]   # grid adjacency of indices
        start = "".join(str(x) for row in board for x in row)
        queue = deque([(start, 0)])
        seen = {start}
        while queue:
            s, d = queue.popleft()
            if s == "123450":
                return d
            i = s.index("0")
            for j in nbr[i]:                                            # slide a neighbouring tile
                t = list(s)
                t[i], t[j] = t[j], t[i]
                t = "".join(t)
                if t not in seen:
                    seen.add(t)
                    queue.append((t, d + 1))
        return -1
